// ===== Idiomas: español e inglés =====
// La clave se comparte con el sitio, así que el idioma elegido en el portal se usa aquí también.
const LANG_KEY = 'arcade.lang';
let LANG = (() => {
  try {
    const s = localStorage.getItem(LANG_KEY);
    if (s === 'es' || s === 'en') return s;
  } catch (e) { /* sin almacenamiento */ }
  return (navigator.language || 'es').toLowerCase().startsWith('es') ? 'es' : 'en';
})();

function setLang(l) {
  LANG = l;
  try { localStorage.setItem(LANG_KEY, l); } catch (e) { /* sin almacenamiento */ }
  document.documentElement.lang = l;
  THUMBS.clear();
}

// Nombre con artículo para los comentarios ("la lavanda", "el tomate", "the lavender")
const FEM_EXTRA = new Set(['strelitzia', 'monstera', 'impatiens']), MASC_EXTRA = new Set(['aloe', 'yellowiris', 'barrel']);
function noun(sp, cap) {
  const n = spName(sp);
  let s;
  if (LANG === 'es') {
    const low = n.charAt(0).toLowerCase() + n.slice(1);
    const fem = FEM_EXTRA.has(sp.id) || (!MASC_EXTRA.has(sp.id) && /a$/.test(n));
    s = (fem ? 'la ' : 'el ') + low;
  } else s = 'the ' + n.charAt(0).toLowerCase() + n.slice(1);
  return cap ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}
const fixES = s => s.replace(/\ba el /g, 'al ').replace(/\bde el /g, 'del ');

// Partes de las estaciones para describir épocas del año
function seasonRangeText(w, parts, seas, all, join) {
  if (w[0] === 0 && w[1] >= 51) return all;
  const sp = d => [seasonOf(d), Math.min(2, Math.floor((d % DAYS_SEASON) / DAYS_SEASON * 3))];
  const [s0, p0] = sp(w[0]), [s1, p1] = sp(w[1]);
  const a = parts[p0] + ' ' + seas[s0], b = parts[p1] + ' ' + seas[s1];
  return a === b ? a : a + join + b;
}

